  <main id="app" aria-live="polite"></main>
  <script>
    const app = document.querySelector('#app');
    const api = async (url, options) => {
      const response = await fetch(url, options);
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || 'Request failed');
      return data;
    };
    function element(tag, text, className) {
      const node = document.createElement(tag);
      if (text !== undefined) node.textContent = text;
      if (className) node.className = className;
      return node;
    }
    async function showList(message = '') {
      app.replaceChildren();
      app.append(element('h1', 'Workboard'));
      if (message) {
        const alert = element('p', message, 'alert');
        alert.setAttribute('role', 'alert');
        app.append(alert);
      }
      const form = document.createElement('form');
      const label = element('label', 'Project name');
      label.htmlFor = 'project-name';
      const input = document.createElement('input');
      input.id = 'project-name'; input.name = 'name'; input.type = 'text'; input.autocomplete = 'off';
      const button = element('button', 'Create project'); button.type = 'submit';
      form.append(label, input, button);
      form.addEventListener('submit', async (event) => {
        event.preventDefault();
        const name = input.value.trim();
        if (!name) return showList('Project name is required');
        try {
          const project = await api('/api/projects', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name }) });
          await showList();
        } catch (error) { showList(error.message); }
      });
      app.append(form);
      const list = element('section');
      list.setAttribute('aria-label', 'Projects');
      try {
        for (const project of await api('/api/projects')) {
          const row = element('div', undefined, 'project-row'); row.dataset.testid = 'project-row';
          row.append(element('span', project.name, 'project-name'));
          const open = element('button', 'Open project'); open.type = 'button';
          open.addEventListener('click', () => { history.pushState({}, '', `/projects/${project.id}`); showProject(project); });
          row.append(open); list.append(row);
        }
      } catch (error) { app.append(element('p', error.message, 'alert')); }
      app.append(list);
    }
    function showProject(project) {
      app.replaceChildren();
      const back = element('button', 'Projects', 'back'); back.type = 'button';
      back.addEventListener('click', () => { history.pushState({}, '', '/'); showList(); });
      app.append(back, element('h1', project.name));
    }
    async function route() {
      const match = location.pathname.match(/^\/projects\/(\d+)\/?$/);
      if (!match) return showList();
      try { showProject(await api(`/api/projects/${match[1]}`)); }
      catch { history.replaceState({}, '', '/'); showList(); }
    }
    addEventListener('popstate', route);
    route();
  </script>
